// single-item input: the config node emits exactly one row.
const cfg = $input.first().json;

const keywords = String(cfg.search_keywords || '')
  .split(',')
  .map((k) => k.trim())
  .filter(Boolean);

if (!keywords.length) {
  throw new Error('Add at least one search term to search_keywords in ' + 'Set Search Config' + '.');
}

// Bright Data's eBay discovery takes {keywords} and nothing else. One search per
// term, and each term adds to the wait, which is why the warning sticky says to
// start with two.
const payload = keywords.map((keywords) => ({ keywords }));

return [{ json: { payload, keywords, scanned_at: new Date().toISOString() } }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the search: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

// Eight listings took 96 seconds in testing. 20 x 15s is five minutes, which
// covers several keywords at the default listing count.
const MAX_POLLS = 20;

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Scrape Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS, search fewer keywords, or lower listings_per_keyword.'
  );
}

return [{ json: { status: res.status, snapshot_id: snapshotId, attempt, records: res.records || 0 } }];

const cfg = $('Set Search Config').first().json;
const minSold = Number(cfg.min_units_sold) || 0;
const minScore = Number(cfg.min_demand_score) || 0;

const median = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

const round = (n, places) => {
  const f = Math.pow(10, places);
  return Math.round(n * f) / f;
};

// Prices arrive as strings with a currency symbol and thousands separators.
const money = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.]/g, ''));
  return isFinite(n) ? n : 0;
};

// A refurbished unit and a new one are not the same market, so they are never
// compared against each other. Template 03 learned this on Google Shopping,
// where used listings dragged the "cheaper offers" band down to nonsense.
const BAND = (c) => {
  const t = String(c || '').toLowerCase();
  if (/parts|not working|for parts/.test(t)) return 'for parts';
  if (/refurb/.test(t)) return 'refurbished';
  if (/open box/.test(t)) return 'open box';
  if (/new/.test(t)) return 'new';
  if (/used|pre-owned|excellent|good|acceptable/.test(t)) return 'used';
  return 'unspecified';
};

const seen = new Set();
const listings = [];
// Everything that parsed into a comparable listing. The digest reports this
// rather than the number of picks, so "48 listings compared, 6 moving" stays
// honest about how much was looked at.
let compared = 0;

for (const item of $input.all()) {
  const j = item.json;
  if (j.error || j.warning) continue;

  const id = String(j.item_id || j.product_id || '');
  if (!id || seen.has(id)) continue;
  seen.add(id);

  const price = money(j.price);
  if (!price) continue;

  const sold = Number(j.quantity_sold != null ? j.quantity_sold : j.sold_count) || 0;
  if (sold < minSold) continue;

  const available = Number(
    j.quantity_available != null ? j.quantity_available : j.available_count
  ) || 0;

  // The live interest signal comes back as free text in three shapes:
  // "10 watched today", "In 13 carts", "3 active offers". eBay's own APIs do
  // not expose any of them, which is the whole reason this reads the page.
  const tagText = (j.tags || []).join(' ');
  const grab = (re) => {
    const m = tagText.match(re);
    return m ? Number(m[1]) : 0;
  };
  const watching = grab(/(\d+)\s+watch/i);
  const inCarts = grab(/in\s+(\d+)\s+cart/i);
  const offers = grab(/(\d+)\s+active\s+offer/i);

  listings.push({
    item_id: id,
    title: String(j.title || '').replace(/\s+/g, ' ').trim(),
    url: String(j.url || ''),
    keyword: String((j.discovery_input && j.discovery_input.keywords) || '').trim(),
    brand: String(j.brand || '').trim(),
    price,
    currency: String(j.currency || 'USD'),
    condition: String(j.condition || '').trim(),
    band: BAND(j.condition),
    sold,
    available,
    watching,
    in_carts: inCarts,
    active_offers: offers,
    seller_name: String(j.seller_name || '').trim(),
    // "99.7% positive feedback" -> 99.7
    seller_positive: money(j.seller_rating),
    seller_reviews: Number(j.seller_total_reviews || j.seller_reviews) || 0,
    shipping: String(j.shipping || '').trim(),
    listing_format: String(j.listing_format || '').trim(),
    item_location: String(j.item_location || '').trim(),
    // Titles on eBay are keyword soup. The model is asked to read this one
    // field and say what the product actually is.
    spec_summary: (j.product_specifications || [])
      .slice(0, 8)
      .map((s) => `${s.specification_name}: ${s.specification_value}`)
      .join('; ')
      .slice(0, 500),
  });
}

if (!listings.length) {
  throw new Error(
    'No listings came back with a readable price. Check the search terms, or ' +
    'lower min_units_sold.'
  );
}

// --- each condition band inside each keyword is its own market --------------
const groups = {};
for (const l of listings) {
  const key = l.keyword + '||' + l.band;
  (groups[key] = groups[key] || []).push(l);
}

const picks = [];
// Listings that never got compared because their band was too thin. Reported
// rather than dropped quietly: on a narrow search this can be most of them, and
// a run that silently ignored half its rows reads like a run that found little.
let thinBand = 0;

for (const group of Object.values(groups)) {
  // Below a handful of listings a median is not a band, it is one listing
  // wearing a hat, and every comparison against it would be noise.
  if (group.length < 4) {
    thinBand += group.length;
    continue;
  }

  const medPrice = median(group.map((l) => l.price));
  const medSold = median(group.map((l) => l.sold));
  compared += group.length;

  for (const l of group) {
    l.band_median_price = round(medPrice, 2);
    l.band_median_sold = medSold;
    l.band_size = group.length;
    l.price_vs_band = medPrice ? round(l.price / medPrice, 2) : 0;

    // --- the demand signals, each worth what it is worth to a reseller ------
    // Units already sold is the only one of these that is a completed
    // transaction, so it carries the most weight. The rest are intent.
    const signals = [];
    const add = (points, key, label) => signals.push({ points, key, label });

    if (medSold && l.sold >= medSold * 2) {
      add(25, 'outsells_band', `${l.sold} sold against a band median of ${medSold}`);
    }
    if (l.watching >= 10) add(20, 'watched', `${l.watching} people watching today`);
    if (l.in_carts >= 5) add(15, 'in_carts', `in ${l.in_carts} carts right now`);
    if (l.available > 0 && l.available <= 3 && l.sold >= 20) {
      add(15, 'thin_stock', `${l.available} left after ${l.sold} sold`);
    }
    if (l.active_offers >= 3) add(10, 'offers', `${l.active_offers} active offers on it`);
    if (medPrice && l.price <= medPrice * 0.8 && l.sold >= medSold) {
      add(12, 'under_band', `priced ${Math.round((1 - l.price / medPrice) * 100)}% under the band and still moving`);
    }
    if (medPrice && l.price >= medPrice * 1.25 && medSold && l.sold >= medSold) {
      add(12, 'over_band', `holding ${Math.round((l.price / medPrice - 1) * 100)}% over the band and still moving`);
    }
    if (l.seller_positive && l.seller_positive < 97) {
      // Not demand, but it changes what the number means: a weak seller moving
      // units says the product carries the listing.
      add(5, 'weak_seller', `seller is at ${l.seller_positive}% positive`);
    }

    l.demand_score = signals.reduce((sum, s) => sum + s.points, 0);
    l.signals = signals.sort((a, b) => b.points - a.points).map((s) => s.label);
    l.signal_keys = signals.map((s) => s.key);

    if (l.demand_score >= minScore) picks.push(l);
  }
}

if (!compared) {
  throw new Error(
    'Not enough listings in any one condition band to build a price band - ' +
    'each needs at least four. Raise listings_per_keyword or use a broader ' +
    'search term.'
  );
}

if (!picks.length) {
  throw new Error(
    compared + ' listings were compared and none scored ' + minScore + ' or ' +
    'more on demand. Lower min_demand_score, or search a category with more ' +
    'movement.'
  );
}

// Stamped after the loop so every row carries the final counts.
for (const p of picks) {
  p.compared = compared;
  p.thin_band = thinBand;
}

return picks
  .sort((a, b) => b.demand_score - a.demand_score)
  .map((json) => ({ json }));

const cfg = $('Set Search Config').first().json;
const limit = Number(cfg.picks_per_run) || 6;
const cooldownDays = Number(cfg.revisit_after_days) || 30;

// The sheet read runs with alwaysOutputData, so on the very first run this is a
// single empty item rather than no items. Treat that as "nothing logged yet"
// instead of letting an undefined row through as a real record.
const logged = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r && r.item_id);

const cutoff = Date.now() - cooldownDays * 86400000;
const recent = new Set(
  logged
    .filter((r) => {
      const t = Date.parse(String(r.logged_at || ''));
      // A row with an unreadable date still counts as logged. Treating it as
      // fair game would put the same listing back in the digest every week.
      return isNaN(t) ? true : t >= cutoff;
    })
    .map((r) => String(r.item_id))
);

const scored = $('Score Listing Demand').all().map((i) => i.json);
const fresh = scored.filter((l) => !recent.has(String(l.item_id)));

// A week where every listing was already reported is a normal outcome, not an
// error. Returning nothing would end the branch here and the IF below would
// never run, so nothing would mark the run as finished - hence one marker item
// with no item_id, which routes to the quiet branch.
if (!fresh.length) {
  return [{
    json: {
      no_new_listings: true,
      compared: scored.length ? scored[0].compared : 0,
      already_logged: scored.length,
    },
  }];
}

return fresh.slice(0, limit).map((json) => ({ json }));

const cfg = $('Set Search Config').first().json;
const picks = $('Select New Listings').all().map((i) => i.json);
// The extractor nests its result under `output` on some versions. Reading the
// item directly gives undefined features on every listing, which produces an
// empty digest on a run where every node is green.
const read = $input.all().map((i) => (i.json && i.json.output) || i.json || {});

const clean = (s, max) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, max);

// The extractor emits one item per input item in the same order, so index
// alignment is the join key.
const rows = picks.map((l, i) => {
  const r = read[i] || {};
  const features = (r.key_features || [])
    .map((f) => String(f || '').toLowerCase().trim())
    .filter((f) => f.length > 2 && f.length < 40)
    .slice(0, 4);

  // The listing's own brand field is the more reliable of the two, because the
  // model is reading a title that may not name a brand at all. "Unbranded" and
  // "Generic" are eBay's placeholders for no brand, and reading "Unbranded
  // GK61" back as a product name is worse than reading "GK61".
  const rawBrand = clean(l.brand || r.brand, 40);
  const brand = /^(unbranded|generic|no brand|unbranded\s*\/\s*generic)$/i.test(rawBrand)
    ? ''
    : rawBrand;
  const productType = clean(r.product_type, 40).toLowerCase();
  const model = clean(r.model, 60);

  // A short name for a listing whose real title is keyword soup. The sheet and
  // the digest both use this; the full title is kept in its own column. The
  // model often repeats the brand inside the model - "AULA" plus "AULA F99
  // Pro" - so the prefix is only added when it is not already there.
  const modelHasBrand =
    brand && model.toLowerCase().startsWith(brand.toLowerCase());
  const name =
    [modelHasBrand ? '' : brand, model].filter(Boolean).join(' ') ||
    l.title.slice(0, 60);

  // The line is assembled from measured fields. Nothing here is the model's
  // opinion of whether the product is good, which is what makes every clause
  // something you can check against the listing page.
  const evidence = l.signals.slice(0, 2).join(', ');
  const band = `${l.price} ${l.currency} against a ${l.band} median of ${l.band_median_price}`;
  const signal = `${name}: ${evidence}. Listed at ${band}.`;

  return {
    ...l,
    brand,
    model,
    product_type: productType,
    key_features: features,
    is_bundle: r.is_bundle === true,
    name,
    signal,
  };
});

const tally = (key) => {
  const m = {};
  for (const r of rows) for (const v of [].concat(r[key] || [])) {
    if (v) m[v] = (m[v] || 0) + 1;
  }
  return Object.entries(m).sort((a, b) => b[1] - a[1]).map(([name, count]) => ({ name, count }));
};

const SIGNAL_NAMES = {
  outsells_band: 'sells far above its band median',
  watched: 'heavy watcher count today',
  in_carts: 'sitting in several carts',
  thin_stock: 'stock running out',
  offers: 'multiple active offers',
  under_band: 'priced under the band and moving',
  over_band: 'holding a premium and moving',
  weak_seller: 'weak seller still moving units',
};

return [{
  json: {
    scanned_at: new Date().toISOString().slice(0, 10),
    keywords: cfg.search_keywords,
    // How many listings were compared inside a band, not how many made the
    // list, and not how many were downloaded.
    compared_count: Number($('Score Listing Demand').first().json.compared) || rows.length,
    // Listings that came back but sat in a band too thin to compare against.
    thin_band_count: Number($('Score Listing Demand').first().json.thin_band) || 0,
    // Everything over the threshold, which is not the same as everything
    // briefed - picks_per_run caps the second number.
    scored_count: $('Score Listing Demand').all().length,
    listed_count: rows.length,
    common_signals: (() => {
      const m = {};
      for (const r of rows) for (const k of r.signal_keys || []) m[k] = (m[k] || 0) + 1;
      return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 5)
        .map(([key, count]) => ({ name: SIGNAL_NAMES[key] || key, count }));
    })(),
    common_features: tally('key_features').slice(0, 5),
    brands: tally('brand').slice(0, 5),
    listings: rows,
  },
}];

parameters.text:
=You are helping a reseller decide what to source next, from this week's eBay demand scan.

Search terms: {{ $json.keywords }}
Listings compared inside a price band: {{ $json.compared_count }}
Listings in front of you: {{ $json.listed_count }}
Signals that came up most: {{ JSON.stringify($json.common_signals) }}
Brands present: {{ JSON.stringify($json.brands) }}
Features buyers are comparing on: {{ JSON.stringify($json.common_features) }}
The listings themselves: {{ JSON.stringify($json.listings.map(l => ({ name: l.name, type: l.product_type, condition: l.band, price: l.price, band_median: l.band_median_price, sold: l.sold, band_median_sold: l.band_median_sold, available: l.available, watching: l.watching, carts: l.in_carts, score: l.demand_score, signals: l.signals }))) }}

Write 4 to 6 sentences covering: which of these is worth sourcing first and why, what the list has in common, and what the price band says about where to list your own.

These are the top few of this week's picks, not all of them, so write about "the listings here" and never state how many cleared the threshold in total. Units sold is a lifetime figure for that listing, not a weekly rate, so do not describe it as a run rate. Watchers and carts are interest, not sales. Never claim a margin or a profit - cost of goods is not in this data. Plain sentences, no bullet points, no headings.

