const data = $('Rank Demand Signals').first().json;
// single-item input: the brief chain is fed one aggregated item and answers with
// one block of prose, so there is no second item to lose here.
const brief = String($input.first().json.text || $input.first().json.output || '').trim();

const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');

// One row per listing, so the sheet doubles as the do-not-repeat list the next
// run reads back.
const rows = data.listings.map((l) => ({
  logged_at: data.scanned_at,
  item_id: l.item_id,
  name: l.name,
  brand: l.brand,
  model: l.model,
  product_type: l.product_type,
  keyword: l.keyword,
  condition: l.condition,
  band: l.band,
  price: l.price,
  currency: l.currency,
  band_median_price: l.band_median_price,
  price_vs_band: l.price_vs_band,
  sold: l.sold,
  band_median_sold: l.band_median_sold,
  available: l.available,
  watching: l.watching,
  in_carts: l.in_carts,
  active_offers: l.active_offers,
  demand_score: l.demand_score,
  seller_name: l.seller_name,
  seller_positive: l.seller_positive,
  shipping: l.shipping,
  item_location: l.item_location,
  key_features: l.key_features.join('; '),
  signals: l.signals.join('; '),
  title: l.title,
  url: l.url,
}));

const held = data.scored_count - data.listed_count;
const lines = [];
lines.push('*eBay demand scan*');
lines.push(
  `${plural(data.compared_count, 'listing')} compared inside a price band, ` +
  `${plural(data.scored_count, 'listing')} moving` +
  // Saying which of the two numbers the list below shows, so a capped run does
  // not read as though only that many listings cleared the threshold.
  (held > 0 ? `, top ${data.listed_count} here.` : '.')
);
if (data.thin_band_count) {
  lines.push(
    `${plural(data.thin_band_count, 'listing')} sat in a condition band with ` +
    'too few others to compare against, and were left out.'
  );
}

lines.push('');
data.listings.slice(0, 6).forEach((l, i) => {
  lines.push(`${i + 1}. *${l.name}* (${l.band}) - score ${l.demand_score}`);
  lines.push(
    `   ${l.price} ${l.currency} vs band median ${l.band_median_price} | ` +
    `${l.sold} sold | ${l.available} left | ${l.watching} watching`
  );
  lines.push(`   ${l.signals.slice(0, 2).join(', ')}`);
  lines.push(`   ${l.url}`);
});

if (data.common_signals.length) {
  lines.push('');
  lines.push('*What is driving the list*');
  lines.push(data.common_signals.map((s) => `${s.name} (${s.count})`).join(', '));
}

if (brief) {
  lines.push('');
  lines.push(brief);
}

// One item carrying both payloads. Split Out turns `rows` into one item per
// listing for the sheet; the Slack node runs once and reads `message` from
// here. Emitting the message as its own item instead would append it to the
// sheet as a row, and post the digest once per listing.
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];
